'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var logcdf = factory( 1.0, 1.0 );
	t.strictEqual( typeof logcdf, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the returned function always returns `NaN`', function test( t ) {
	var logcdf;

	logcdf = factory( NaN, 1.0 );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	logcdf = factory( 1.0, NaN );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	logcdf = factory( NaN, NaN );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a non-positive `alpha`, the returned function always returns `NaN`', function test( t ) {
	var logcdf;

	logcdf = factory( 0.0, 1.0 );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	logcdf = factory( -1.0, 1.0 );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	logcdf = factory( NINF, 1.0 );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a non-positive `beta`, the returned function always returns `NaN`', function test( t ) {
	var logcdf;

	logcdf = factory( 1.0, 0.0 );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	logcdf = factory( 1.0, -1.0 );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	logcdf = factory( 1.0, NINF );
	t.strictEqual( isnan( logcdf( 1.0 ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the returned function returns `NaN` if provided `NaN` for `x`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 1.0, 1.0 );

	y = logcdf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the returned function returns `-Infinity` if provided `x <= 0`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 1.0, 1.0 );

	y = logcdf( 0.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	y = logcdf( -1.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	y = logcdf( NINF );
	t.strictEqual( y, NINF, 'returns expected value' );

	t.end();
});

tape( 'the returned function does not overflow for large `x` (approaching zero)', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 1.0, 60.0 );
	y = logcdf( 1.0e6 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	logcdf = factory( 1.0, 5.0 );
	y = logcdf( 1.0e300 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the returned function evaluates the log-logistic logcdf for positive `x`, `alpha`, and `beta`', function test( t ) {
	var expected;
	var logcdf;
	var alpha;
	var beta;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.x;
	alpha = data.alpha;
	beta = data.beta;
	for ( i = 0; i < x.length; i++ ) {
		logcdf = factory( alpha[ i ], beta[ i ] );
		y = logcdf( x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 2 ), true, 'x: '+x[ i ]+', alpha: '+alpha[ i ]+', beta: '+beta[ i ]+', y: '+y+', expected: '+expected[ i ] );
	}
	t.end();
});
